async def run_turn(session: ClientSession, reply) -> list[dict]:
    tools = {t.name: t for t in (await session.list_tools()).tools}
    results = []
    for call in reply.tool_calls:
        tool = tools[call.name]
        if tool.annotations and tool.annotations.destructiveHint:
            log.info("running destructive tool %s", call.name)
        res = await session.call_tool(call.name, call.arguments)
        results.append({"tool_call_id": call.id, "content": res.content[0].text})
    return results

