def load_tools(mcp: FastMCP) -> None:
    raw = TOOLS_FILE.read_bytes()
    if hashlib.sha256(raw).hexdigest() != TOOLS_SHA256:
        raise RuntimeError("tool definitions do not match the pinned hash")
    for spec in json.loads(raw):
        mcp.add_tool(HANDLERS[spec["handler"]], name=spec["name"], description=spec["description"])

