class Confirm(BaseModel):
    confirm: bool

@mcp.tool()
async def rotate_api_key(key_id: int, ctx: Context) -> str:
    """Rotate a production API key."""
    user = current_user(ctx)
    key = api_keys.get_for_org(key_id, user.org_id)
    if key is None or not user.is_admin:
        raise PermissionError("not allowed")
    answer = await ctx.elicit(f"Rotate key {key.prefix}? The old key stops working now.", schema=Confirm)
    if answer.action != "accept" or not answer.data.confirm:
        return "cancelled"
    return api_keys.rotate(key, revoke_old=True).prefix

ALLOWED_HOSTS = {"images.example.com"}

@mcp.tool()
async def product_photo(url: HttpUrl) -> bytes:
    """Download a product photo from the Acme image CDN."""
    if url.scheme != "https" or url.host not in ALLOWED_HOSTS:
        raise ValueError("only Acme CDN images are allowed")
    async with httpx.AsyncClient(timeout=10, follow_redirects=False) as http:
        r = await http.get(str(url))
    r.raise_for_status()
    return r.content[:5_000_000]
